// Loam as generated by Lux3D: image -> 3D model -> humanoid auto-rig -> animation retarget.
// Clips are blended with cross-fades and layered with procedural squash/stretch, lean and flip.

import * as THREE from 'three';
import { loadGLTF, BASE, getManifest, loadModel } from '../core/Assets';
import type { Player, PlayerAnim, PlayerEvent } from './Player';
import { FORMS, Form } from './forms';
import { HeroVisual, Juice, addRim } from './HeroVisual';
import { VLight } from '../render/LightPool';
import { makeSoftDot } from '../render/noise';

const CLIPS: Record<PlayerAnim, { clip: string; loop: boolean; speed?: number; fade?: number; then?: string }> = {
  idle: { clip: 'Idle_Loop', loop: true },
  run: { clip: 'Jog_Fwd_Loop', loop: true, speed: 1.15 },
  sprint: { clip: 'Sprint_Loop', loop: true },
  walk: { clip: 'Walk_Loop', loop: true, speed: 1.1 },
  wade: { clip: 'Walk_Loop', loop: true, speed: 0.7 },
  jump: { clip: 'Jump_Start', loop: false, speed: 1.6, fade: 0.08, then: 'Jump_Loop' },
  fall: { clip: 'Jump_Loop', loop: true, fade: 0.2 },
  flip: { clip: 'NinjaJump_Start', loop: false, speed: 1.4, fade: 0.06, then: 'NinjaJump_Idle_Loop' },
  wall: { clip: 'Jump_Loop', loop: true, speed: 0.6 },
  dash: { clip: 'Roll', loop: false, speed: 2.2, fade: 0.05 },
  charge: { clip: 'Sprint_Loop', loop: true, speed: 1.4, fade: 0.05 },
  pound: { clip: 'NinjaJump_Idle_Loop', loop: true, fade: 0.05 },
  push: { clip: 'Push_Loop', loop: true },
  swim: { clip: 'Swim_Fwd_Loop', loop: true },
  swimIdle: { clip: 'Swim_Idle_Loop', loop: true },
  climb: { clip: 'ClimbUp_1m', loop: false, speed: 2.6, fade: 0.05 },
  cast: { clip: 'Spell_Simple_Idle_Loop', loop: true },
  interact: { clip: 'Interact', loop: false, speed: 1.6, fade: 0.1 },
  hurt: { clip: 'Hit_Knockback', loop: false },
  dead: { clip: 'Death01', loop: false },
  wake: { clip: 'LayToIdle', loop: false, speed: 1.0, fade: 0.01, then: 'Idle_Loop' },
  lying: { clip: 'LayToIdle', loop: false, speed: 0, fade: 0.01 },
  sit: { clip: 'Sitting_Enter', loop: false, then: 'Sitting_Idle_Loop' },
  dance: { clip: 'Dance_Loop', loop: true },
};

const HEIGHT = 1.2;

export class RiggedHero implements HeroVisual {
  readonly root = new THREE.Group();
  private model!: THREE.Object3D;
  private mixer!: THREE.AnimationMixer;
  private actions = new Map<string, THREE.AnimationAction>();
  private current: THREE.AnimationAction | null = null;
  private currentAnim: PlayerAnim | null = null;
  private forced: PlayerAnim | null = null;
  private juice = new Juice();
  private materials: THREE.MeshStandardMaterial[] = [];
  private baseMaps = new Map<THREE.MeshStandardMaterial, THREE.Texture | null>();
  private formMaps = new Map<Form, THREE.Texture | null>();
  private heartLight = new VLight(0xffa040, 2, 4, 2);
  private heartGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: makeSoftDot(64), color: 0xffa040, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
  private heartAnchor = new THREE.Object3D();
  private spine: THREE.Object3D | null = null;
  private head: THREE.Object3D | null = null;
  private neck: THREE.Object3D | null = null;
  lookAt: THREE.Vector3 | null = null;
  private lookYaw = 0;
  private lookPitch = 0;
  private bank = 0;
  private prevYaw = 0;
  private tmpV = new THREE.Vector3();
  private t = 0;
  private transformFlash = 0;

  static async create(): Promise<RiggedHero | null> {
    const m = getManifest();
    const rig = await loadModel('hero_rig');
    if (!rig) return null;
    const h = new RiggedHero();
    await h.setup(rig.scene, m.anims || {});
    return h;
  }

  private async setup(scene: THREE.Object3D, anims: Record<string, string>) {
    this.model = scene;
    const box = new THREE.Box3().setFromObject(scene);
    const size = box.getSize(new THREE.Vector3());
    const s = HEIGHT / Math.max(size.y, 1e-3);
    scene.scale.setScalar(s);
    const box2 = new THREE.Box3().setFromObject(scene);
    scene.position.y -= box2.min.y;
    const c = box2.getCenter(new THREE.Vector3());
    scene.position.x -= c.x;
    scene.position.z -= c.z;
    const inner = new THREE.Group();
    inner.add(scene);
    this.root.add(inner);
    scene.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (mesh.isMesh) {
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.frustumCulled = false;
        const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        const upgraded = mats.map((mm) => {
          const src = mm as THREE.MeshStandardMaterial;
          const pm = new THREE.MeshPhysicalMaterial({
            map: src.map ?? null,
            normalMap: src.normalMap ?? null,
            roughnessMap: src.roughnessMap ?? null,
            metalnessMap: src.metalnessMap ?? null,
            color: src.color ?? new THREE.Color(0xffffff),
            roughness: src.roughness ?? 0.8,
            metalness: src.metalness ?? 0,
          });
          this.materials.push(pm);
          addRim(pm, 0xffb070, 0.35, 0);
          this.baseMaps.set(pm, pm.map);
          return pm;
        });
        mesh.material = Array.isArray(mesh.material) ? upgraded : upgraded[0];
      }
      const name = o.name.toLowerCase();
      if (!this.spine && (name.includes('spine2') || name.includes('chest') || name.includes('spine1') || name === 'spine')) this.spine = o;
      if (!this.head && /head$/.test(name)) this.head = o;
      if (!this.neck && /neck$/.test(name)) this.neck = o;
    });
    this.heartAnchor.position.set(0, HEIGHT * 0.62, 0.2);
    // keep the warm heart light well clear of the body: very close point lights blow out PBR specular
    this.heartLight.position.copy(this.heartAnchor.position).add(new THREE.Vector3(0, 0.1, 0.9));
    this.heartLight.distance = 3.5;
    // The heart light is a pooled VLight kept half a metre in front of the chest: it warms the
    // ground ahead of Loam without sitting on the skin (very close lights blew out specular).
    this.heartLight.position.copy(this.heartAnchor.position).add(new THREE.Vector3(0, 0.15, 0.55));
    this.heartLight.priority = 2;
    inner.add(this.heartAnchor, this.heartLight);
    // a soft glow on the chest so the amber heart reads from any distance
    this.heartGlow.position.copy(this.heartAnchor.position).add(new THREE.Vector3(0, 0, 0.06));
    this.heartGlow.scale.setScalar(0.28);
    this.heartGlow.renderOrder = 15;
    inner.add(this.heartGlow);
    this.mixer = new THREE.AnimationMixer(scene);
    // only the retargeted hero clips (anims/); other entries, like the Colossus articulation, live in models/
    const heroClips = Object.entries(anims).filter(([, file]) => file.startsWith('anims/'));
    const loads = heroClips.map(async ([id, file]) => {
      const g = await loadGLTF(BASE + file);
      const clip = g?.animations?.[0];
      if (!clip) return;
      clip.name = id;
      // strip root translation in x/z so in-place clips never drift
      for (const track of clip.tracks) {
        if (track.name.endsWith('.position') && /hips|root|pelvis/i.test(track.name)) {
          const v = track.values;
          for (let i = 0; i < v.length; i += 3) {
            v[i] = v[0];
            v[i + 2] = v[2];
          }
        }
      }
      const action = this.mixer.clipAction(clip);
      this.actions.set(id, action);
    });
    await Promise.all(loads);
    // per-form textures produced by Lux3D material transfer
    for (const f of ['stone', 'wood', 'glass'] as Form[]) {
      const g = await loadModel(`hero_${f}`);
      let map: THREE.Texture | null = null;
      g?.scene.traverse((o) => {
        const mm = (o as THREE.Mesh).material as THREE.MeshStandardMaterial | undefined;
        if (!map && mm?.map) map = mm.map;
      });
      this.formMaps.set(f, map);
    }
    this.play('idle', true);
  }

  private play(anim: PlayerAnim, instant = false) {
    if (anim === this.currentAnim) return;
    this.currentAnim = anim;
    const spec = CLIPS[anim];
    let action = this.actions.get(spec.clip);
    if (!action) action = this.actions.get(spec.loop ? 'Idle_Loop' : 'Jump_Loop') ?? this.actions.get('Idle_Loop');
    if (!action) return;
    const fade = instant ? 0 : spec.fade ?? 0.18;
    action.reset();
    action.enabled = true;
    action.setEffectiveTimeScale(spec.speed ?? 1);
    action.setEffectiveWeight(1);
    action.setLoop(spec.loop ? THREE.LoopRepeat : THREE.LoopOnce, Infinity);
    action.clampWhenFinished = !spec.loop;
    if (this.current && this.current !== action) action.crossFadeFrom(this.current, fade, false);
    action.play();
    this.current = action;
    if (spec.then) {
      const next = this.actions.get(spec.then);
      if (next) {
        const onFinish = (e: { action: THREE.AnimationAction }) => {
          if (e.action !== action) return;
          this.mixer.removeEventListener('finished', onFinish);
          if (this.current !== action) return;
          next.reset();
          next.setLoop(THREE.LoopRepeat, Infinity);
          next.setEffectiveTimeScale(1);
          next.setEffectiveWeight(1);
          next.crossFadeFrom(action, 0.15, false);
          next.play();
          this.current = next;
        };
        this.mixer.addEventListener('finished', onFinish);
      }
    }
  }

  setForm(form: Form) {
    const map = form === 'clay' ? null : this.formMaps.get(form) ?? null;
    for (const m of this.materials) {
      const pm = m as THREE.MeshPhysicalMaterial;
      pm.map = map ?? this.baseMaps.get(m) ?? null;
      const s = FORMS[form];
      pm.roughness = s.roughness;
      pm.metalness = s.metalness;
      pm.transmission = 0;
      pm.transparent = form === 'glass';
      pm.opacity = form === 'glass' ? 0.6 : 1;
      pm.depthWrite = form !== 'glass';
      pm.clearcoat = form === 'glass' ? 1 : 0;
      pm.color.setHex(map || form === 'clay' ? 0xffffff : s.color);
      pm.emissive.setHex(form === 'glass' ? 0x1a6f80 : 0x000000);
      addRim(pm, form === 'glass' ? 0x8ff0ff : s.emissive, form === 'glass' ? 0.9 : 0.35, form === 'glass' ? 1 : 0);
      pm.needsUpdate = true;
    }
    this.heartLight.color.setHex(FORMS[form].emissive);
    (this.heartGlow.material as THREE.SpriteMaterial).color.setHex(FORMS[form].emissive).multiplyScalar(2.2);
    this.transformFlash = 1;
    this.juice.kick(-4);
  }

  forceAnim(a: PlayerAnim | null) {
    this.forced = a;
    if (a) this.play(a, a === 'lying');
    else this.currentAnim = null;
  }

  heartPosition(out: THREE.Vector3) {
    return this.heartAnchor.getWorldPosition(out);
  }

  onEvent(e: PlayerEvent) {
    if (e === 'jump' || e === 'walljump') this.juice.kick(4.5);
    if (e === 'flip') {
      this.juice.kick(3);
      this.juice.startFlip();
    }
    if (e === 'land') this.juice.kick(-4.5);
    if (e === 'hardLand' || e === 'poundImpact') this.juice.kick(-8);
    if (e === 'dash') this.juice.kick(-2.5);
  }

  /** Seconds Loam has stood still with control (drives the idle sit-down). */
  private idleFor = 0;

  update(dt: number, p: Player) {
    this.t += dt;
    this.juice.update(dt, p);
    // left alone for a while, Loam sits down to rest (Lux3D retargeted sitting clips) and springs
    // back up the moment the player moves
    this.idleFor = !this.forced && p.anim === 'idle' && p.control && p.grounded ? this.idleFor + dt : 0;
    const resting = this.idleFor > 9;
    const anim = this.forced ?? (resting ? 'sit' : p.anim);
    this.play(anim);
    if (this.current && (anim === 'run' || anim === 'sprint' || anim === 'walk')) {
      const base = CLIPS[anim].speed ?? 1;
      this.current.setEffectiveTimeScale(base * THREE.MathUtils.clamp(p.speedRatio, 0.55, 1.4));
    }
    this.mixer.update(dt);
    const j = this.juice;
    this.root.position.set(p.cx, p.body.y, p.cz);
    this.root.rotation.set(0, j.yaw, 0);
    const inner = this.root.children[0];
    inner.rotation.set(0, 0, 0);
    if (j.flip > 0) inner.rotation.x = -j.flip;
    if (anim === 'wall') inner.rotation.y = Math.PI;
    // keep the head and shoulders above the (depth-writing) water surface so Loam stays readable
    if (anim === 'swim' || anim === 'swimIdle') inner.position.y = 0.12;
    else inner.position.y = 0;
    if (this.spine) this.spine.rotation.x += j.lean * 0.5;
    // the head (and a little of the neck) turns toward whatever is worth looking at
    let wantYaw = 0;
    let wantPitch = 0;
    if (this.lookAt && this.head && !this.forced) {
      this.head.getWorldPosition(this.tmpV);
      const dx = this.lookAt.x - this.tmpV.x;
      const dy = this.lookAt.y - this.tmpV.y;
      const dz = this.lookAt.z - this.tmpV.z;
      let rel = Math.atan2(dx, dz) - j.yaw;
      rel = ((rel + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI;
      if (Math.abs(rel) < 2.0) {
        wantYaw = THREE.MathUtils.clamp(rel, -1.0, 1.0);
        wantPitch = THREE.MathUtils.clamp(Math.atan2(dy, Math.hypot(dx, dz)), -0.45, 0.4);
      }
    }
    const kl = 1 - Math.exp(-dt * 5);
    this.lookYaw += (wantYaw - this.lookYaw) * kl;
    this.lookPitch += (wantPitch - this.lookPitch) * kl;
    if (this.neck) this.neck.rotateY(this.lookYaw * 0.35);
    if (this.head) {
      this.head.rotateY(this.lookYaw * 0.65);
      this.head.rotateX(-this.lookPitch * 0.7);
    }
    // bank into turns while running
    let yawRate = j.yaw - this.prevYaw;
    yawRate = ((yawRate + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI;
    this.prevYaw = j.yaw;
    const running = p.grounded && (anim === 'run' || anim === 'sprint');
    const wantBank = running && dt > 0 ? THREE.MathUtils.clamp((-yawRate / dt) * p.hspeed * 0.012, -0.22, 0.22) : 0;
    this.bank += (wantBank - this.bank) * (1 - Math.exp(-dt * 8));
    inner.rotation.z += this.bank;
    this.root.scale.set(1 / Math.sqrt(j.scaleY), j.scaleY, 1 / Math.sqrt(j.scaleY));
    this.transformFlash = Math.max(0, this.transformFlash - dt * 2);
    for (const m of this.materials) (m as THREE.MeshPhysicalMaterial).emissiveIntensity = 1 + this.transformFlash * 3;
    this.heartLight.intensity = 1.4 + Math.sin(this.t * 3) * 0.4 + this.transformFlash * 10;
    this.heartGlow.material.opacity = 0.55 + Math.sin(this.t * 3) * 0.2 + this.transformFlash * 0.45;
  }
}
